print(len(idxs))
for k in idxs:
    seg=t[k-50:k+4000]
    m=re.search(r'(\[\[6, 1.*?\]\])', seg, re.S)
    if m:
        try:
            g=json.loads(m.group(1))
            print('rows',len(g),'col9',[r[9] for r in g])
        except Exception as e:
            print('err',e)
